export function npcCommands(base,seed,level=1){let r=rng(seed),weights=[-7.8,0,7.8],scores=weights.map(x=>base.filter(b=>BUILD[b.type].damage).reduce((n,b)=>n+Math.max(0,8-Math.hypot(b.x-x,b.z-6))*BUILD[b.type].damage/40,0)),side=weights[scores.indexOf(Math.min(...scores))],tactic=seed%5,cmd=[];let boatCount=level===1?1+(seed%2===0?1:0):Math.min(1+Math.floor(level/2)+(seed%2===0?1:0),4),boatCap=HQ_TIERS[Math.max(1,Math.min(MAX_HQ_LEVEL,level))].boatCapacity,types=tactic===0?['rifle','rifle','rifle']:tactic===1?['heavy','rocket','heavy']:tactic===2?['tank','medic','heavy']:tactic===3?['rifle','rocket','heavy']:['heavy','rocket','medic'];for(let boat=0;boat<boatCount;boat++){let type=types[boat%types.length];if((type==='tank'||type==='medic')&&level<2)type='heavy';let count=Math.max(1,Math.floor(boatCap/UNIT[type].space*.55));let x=tactic===3?(boat%2?-7.4:7.4):side+(r()-.5)*1.3;cmd.push({t:5+boat*48,kind:'land',type,count,index:boat,level:Math.max(1,level-1),capacity:boatCap,x:Math.max(-MAP.landX,Math.min(MAP.landX,x))})}cmd.push({t:75,kind:'fire',x:base.find(b=>b.type==='hq').x,z:base.find(b=>b.type==='hq').z});return {tactic:TACTICS[tactic],commands:cmd}}

export function runCommands(b,commands,maxTicks=BATTLE_LIMIT_TICKS){let i=0;while(!b.done&&b.tick<maxTicks){while(i<commands.length&&commands[i].t<=b.tick){let c=commands[i++];if(c.kind==='deploy')b.deploy(c.type,c.x,true,c.level||1);else if(c.kind==='land')b.landBoat(c.type,c.count,c.x,c.index,c.level||1,true,c.z,c.capacity);else b.useSkill(c.kind,c.x,c.z,c.id,true,c.aimQuality??1,c.heading)}b.step();if(!b.done&&b.tick>240&&i>=commands.length&&!b.gunboatShells.length&&b.landings.every(l=>l.released)&&b.units.every(u=>u.hp<=0||u.type==='medic')){b.done=true;b.outcome='失败';b.cause='部队全灭'}}return b}
export function checkRaid(s,now=Date.now(),sourceAt=s.lastAt){if(now<s.raidAt||now<s.protectedUntil)return null;let roll=rng(mix32((s.seed^Math.floor(sourceAt/1000)^Math.imul(s.encounter+1,1103515245))>>>0))();if(roll<.35)return {attempted:true,report:simulateRaid(s,now)};s.raidAt=now+8*3600000;return {attempted:true,report:null}}
export function recordOnline(s,deltaMs,now=Date.now()){let date=new Date(now),day=[date.getFullYear(),date.getMonth()+1,date.getDate()].join('-');if(s.onlineClock?.day!==day)s.onlineClock={day,ms:0,gates:0};let clock=s.onlineClock;clock.ms+=Math.max(0,deltaMs);let passed=Math.min(2,Math.floor(clock.ms/(8*3600000)));if(passed>clock.gates){clock.gates=passed;return true}return false}
export function simulateRaid(s,now=Date.now()){let seed=(s.seed+Math.floor(s.raidAt/3600000))>>>0,{commands,tactic}=npcCommands(s.base,seed,hqLevel(s)),period=battlePeriodAt(s.timeAnchor,now),battle=runCommands(new Battle(s.base,seed,'defense',null,hqLevel(s),MAP.spawnZ,CURRENT_RULESET,s.gunboat?.weaponLevels,period.id,period.progress),commands);let lost={gold:0,wood:0,steel:0};if(battle.outcome==='胜利')for(let k of RES){lost[k]=Math.floor(Math.max(0,s.resources[k]-raidProtection(s,k).total)*.14);s.resources[k]-=lost[k]}let rep={at:now,kind:'防守',outcome:battle.outcome==='胜利'?'失守':'守住',tactic,lost,replay:battle.snapshot(),destruction:battle.destruction};s.reports.unshift(rep);s.reports=s.reports.slice(0,15);s.raidAt=now+8*3600000;s.protectedUntil=now+6*3600000;return rep}
export function resolveAttack(s,enemy,b,now=Date.now()){let gained=rewardFor(enemy,b);for(let k of RES)s.resources[k]=Math.min(storage(s,k),s.resources[k]+gained[k]);if(b.outcome==='胜利')s.won++;else s.lost++;let returned=Object.fromEntries(Object.keys(UNIT).map(k=>[k,0]));for(let u of b.units)if(u.hp>0)returned[u.type]++;for(let l of b.landings)if(!l.released)returned[l.type]+=l.count-l.releasedCount;for(let [type,n] of Object.entries(returned))s.army[type]+=n;let rep={at:now,kind:'进攻',outcome:b.outcome,destruction:b.destruction,gained,returned,replay:b.snapshot()};s.reports.unshift(rep);s.reports=s.reports.slice(0,15);s.encounter++;delete s.activeBattle;return rep}
export function replayBattle(rep){let b=new Battle(rep.base,rep.seed,'replay',null,rep.gunboatLevel||1,rep.spawnZ??(rep.version>=12?MAP.spawnZ:rep.version>=2?LEGACY_MAP.spawnZ:5.5),rep.version>=30?30:rep.version>=29?29:rep.version>=28?28:rep.version>=27?27:rep.version>=26?26:rep.version>=25?25:rep.version>=24?24:rep.version>=23?23:rep.version>=22?22:rep.version>=21?21:rep.version>=20?20:rep.version>=19?19:rep.version>=18?18:rep.version>=17?17:rep.version>=16?16:rep.version>=15?15:rep.version>=14?14:rep.version>=13?13:rep.version>=12?12:rep.version>=11?11:rep.version>=10?10:rep.version>=9?9:rep.version>=8?8:rep.version>=7?7:rep.version>=6?6:rep.version>=5?5:rep.version>=4?4:rep.version>=3?3:2,rep.weaponLevels,rep.period||'standard',rep.periodProgress??.5),commands=clone(rep.commands).sort((a,c)=>a.t-c.t);b.stopTick=rep.ticks;b.expectedOutcome=rep.outcome;b.originalRole=rep.role;return {battle:b,commands}}
const OLD_STARTER=['gold','wood','steel','store','sniper','mg','mortar','cannon'];
function migrateOldStarter(s,now){let hq=s.base.find(b=>b.type==='hq');if(!hq||hq.lvl!==1)return;
 let oldShell=OLD_STARTER.every((type,i)=>s.base.some(b=>b.id===i+2&&b.type===type&&b.lvl===1));
 let remove=new Set(s.base.filter(b=>BUILD[b.type]?.damage&&BUILD_UNLOCK[b.type]>1).map(b=>b.id));
 if(oldShell)for(let id=2;id<=9;id++)remove.add(id);
 if(!remove.size)return;
 s.base=s.base.filter(b=>!remove.has(b.id));s.upgrades=(s.upgrades||[]).filter(u=>!remove.has(u.id));
 if(oldShell){let starter={gold:1500,wood:1250,steel:820};for(let key of RES)s.resources[key]=Math.max(s.resources[key]||0,starter[key]);s.guideStep=0;s.tutorialDone=false;s.onboardSeen=true}
 s.protectedUntil=Math.max(s.protectedUntil||0,now+24*3600000);s.raidAt=Math.max(s.raidAt||0,now+24*3600000);
 s.migrationNotice=oldShell?'已收回旧版预置建筑；保留资源、部队和战报。先在商店建矿场。':'已收回当前司令部等级尚未解锁的旧版防御建筑。';
}
function removeIdlePersonnel(s){let refunded=0,legacy=(s.training||[]).filter(t=>t.type);for(let t of legacy)refunded+=trainingCost(t.type);s.training=(s.training||[]).filter(t=>!t.type);let assigned=Object.fromEntries(Object.keys(UNIT).map(type=>[type,0]));for(let boat of boatManifest(s))assigned[boat.type]+=boat.count;for(let type of Object.keys(UNIT)){let extra=Math.max(0,(s.army[type]||0)-assigned[type]);if(extra){s.army[type]-=extra;refunded+=extra*trainingCost(type)}}if(refunded){s.resources.gold=Math.min(storage(s),s.resources.gold+refunded);let note='0.5 已取消闲置人员并退回 🟡'+refunded+'；新兵只能由具体登陆艇补员或换装。';s.migrationNotice=s.migrationNotice?s.migrationNotice+' '+note:note}}
export function migrateResourceSites(s){
 if(s.resourceSiteStorage){for(let b of s.base)if(RES.includes(b.type))b.stored=Math.max(0,Number(b.stored)||0);return syncUncollected(s)}
 let legacy=Object.fromEntries(RES.map(key=>[key,Math.max(0,Number(s.uncollected?.[key])||0)])),moved=RES.some(key=>legacy[key]>0);
 for(let key of RES){let sites=s.base.filter(b=>b.type===key),remaining=legacy[key];for(let site of sites){site.stored=0;let amount=Math.min(remaining,resourceSiteCapacity(site));site.stored=amount;remaining-=amount}if(remaining>0&&sites.length){sites.at(-1).stored+=remaining;remaining=0}if(remaining>0)s.resources[key]=(Number(s.resources[key])||0)+remaining}
 s.resourceSiteStorage=true;syncUncollected(s);if(moved){let note='0.5.2 已把待收资源迁回各自资源点的现场仓库。';s.migrationNotice=s.migrationNotice?s.migrationNotice+' '+note:note}return s.uncollected
}
export function enforceSingleIndustrySites(s){let removed={wood:0,steel:0};for(let type of ['wood','steel']){let sites=s.base.filter(b=>b.type===type);if(sites.length<=1)continue;sites.sort((a,b)=>(b.lvl||1)-(a.lvl||1)||Number(!!a.constructionEnd)-Number(!!b.constructionEnd)||(a.id||0)-(b.id||0));let keep=sites[0],discard=sites.slice(1),ids=new Set(discard.map(b=>b.id));keep.stored=sites.reduce((n,b)=>n+Math.max(0,Number(b.stored)||0),0);s.base=s.base.filter(b=>!ids.has(b.id));s.upgrades=(s.upgrades||[]).filter(u=>!ids.has(u.id));removed[type]=discard.length}syncUncollected(s);let total=removed.wood+removed.steel;if(total){let parts=[];if(removed.wood)parts.push('伐木场×'+removed.wood);if(removed.steel)parts.push('钢厂×'+removed.steel);let note='更新后已拆除多余'+parts.join('、')+'；未收取资源已并入保留的最高级资源点。';s.migrationNotice=s.migrationNotice?s.migrationNotice+' '+note:note}return removed}

export function enforceSingleVault(s,now=Date.now()){
 let sites=s.base.filter(b=>b.type==='vault'),refund=Object.fromEntries(RES.map(k=>[k,0]));if(sites.length<=1)return {removed:0,refund};
 let order=new Map([...sites].sort((a,b)=>(a.id||0)-(b.id||0)).map((b,i)=>[b.id,i]));
 sites.sort((a,b)=>(b.lvl||1)-(a.lvl||1)||Number(!!a.constructionEnd)-Number(!!b.constructionEnd)||(a.id||0)-(b.id||0));
 let discarded=sites.slice(1),ids=new Set(discarded.map(b=>b.id)),add=cost=>RES.forEach((key,i)=>refund[key]+=cost[i]);
 for(let b of discarded){add(buildCost('vault',order.get(b.id)));for(let level=1;level<(b.lvl||1);level++)add(upgradeCost({type:'vault',lvl:level}));if((s.upgrades||[]).some(u=>u.id===b.id))add(upgradeCost(b))}
 s.base=s.base.filter(b=>!ids.has(b.id));s.upgrades=(s.upgrades||[]).filter(u=>!ids.has(u.id));
 // Refunds remain collectible even when the normal inventory is full, like preserved on-site resources from earlier migrations.
 for(let key of RES){let site=s.base.filter(b=>b.type===key).sort((a,b)=>(b.lvl||1)-(a.lvl||1))[0];if(site){let overflow=Math.max(0,(Number(s.resources[key])||0)-storage(s,key,now));s.resources[key]-=overflow;site.stored=Math.max(0,Number(site.stored)||0)+refund[key]+overflow}else s.resources[key]=(Number(s.resources[key])||0)+refund[key]}
 syncUncollected(s);let note='保险库全基地最多一座；已保留最高级保险库，多余保险库的建造和升级资源已退回。';s.migrationNotice=s.migrationNotice?s.migrationNotice+' '+note:note;return {removed:discarded.length,refund};
}
export function loadSave(storeBackend=globalThis.localStorage,now=Date.now()){try{let data=JSON.parse(storeBackend.getItem(SAVE_KEY));if([1,2,3,4,5].includes(data?.version)&&data.resources&&Array.isArray(data.base)&&data.army){data.craft??={count:3,level:1};data.craft.loadouts??=['rifle','heavy','rocket'];data.craft.refits??=[];data.craft.refills??=[];data.craft.reserved??=[];while(data.craft.loadouts.length<data.craft.count)data.craft.loadouts.push('rifle');data.craft.levels??=Array(data.craft.count).fill(data.craft.level||1);while(data.craft.levels.length<data.craft.count)data.craft.levels.push(1);data.gunboat??={level:1};data.gunboat.weaponLevels??={};for(let kind of Object.keys(SKILLS))data.gunboat.weaponLevels[kind]=Math.max(1,Math.min(MAX_WEAPON_LEVEL,Math.floor(data.gunboat.weaponLevels[kind])||1));data.unitLevels??={rifle:1,heavy:1,rocket:1,tank:1,medic:1};data.uncollected??={gold:0,wood:0,steel:0};data.upgrades??=[];data.training??=[];data.reports??=[];data.timeAnchor=Number.isFinite(data.timeAnchor)?data.timeAnchor:battleTimeAnchor(data.seed||88241,now);if(!data.expandedIsland){for(let building of data.base){building.x=+(building.x*1.35).toFixed(2);building.z=+(building.z*1.35).toFixed(2)}data.expandedIsland=true}if(data.activeBattle){data.army=data.activeBattle.initialArmy;data.resources.gold=Math.min(storage(data),data.resources.gold+(data.activeBattle.deploymentGoldPaid||0)+(data.activeBattle.entryGoldPaid||0));delete data.activeBattle}if(data.version<4)migrateOldStarter(data,now);migrateResourceSites(data);enforceSingleIndustrySites(data);enforceSingleVault(data,now);data.version=5;for(let r of data.reports)if(r.kind==='防守'&&r.outcome==='胜利')r.outcome='失守';else if(r.kind==='防守'&&r.outcome==='失败')r.outcome='守住';settle(data,now,true);removeIdlePersonnel(data);return data}}catch(e){console.warn('Save unreadable',e)}return createSave(now)}
export function saveGame(s,storage=globalThis.localStorage){storage.setItem(SAVE_KEY,JSON.stringify(s))}
